Fungsi berikut menjumlahkan semua elemen dalam daftar:
def jumlah_elemen(daftar):
    return sum(daftar)

Contoh: jumlah_elemen([1, 2, 3]) menghasilkan 6.

def pangkat(basis, eksponen):
    return basis ** eksponen

Contoh: print(pangkat(2, 3))  # Output: 8

def ambil_genap(daftar):
    return [x for x in daftar if x % 2 == 0]
Contoh: print(ambil_genap([1,2,3,4,5,6]))  # output: [2,4,6]

def min_max(daftar):
    if not daftar:
        return (None, None)
    return (min(daftar), max(daftar))

Contoh: print(min_max([3,1,4,1,5]))  # Output: (1,5)

